def luminance(h):
 a=[int(h[i:i+2],16)/255 for i in (1,3,5)];a=[v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4 for v in a];return .2126*a[0]+.7152*a[1]+.0722*a[2]
ratio=(luminance('#dfe8f5')+.05)/(luminance('#246cac')+.05)
